# Generates the `front_end/generated` files that are based on files living in
# Blink and are still committed. The protocol types, ARIAProperties.ts and
# Deprecation.ts are generated by the build instead (see
# front_end/generated/BUILD.gn); the build reads the copy of the Blink and V8
# files that scripts/deps/roll_deps.py keeps in this repository, so DevTools is
# still built against the CDP version it was rolled to rather than the one at
# Chromium's tip of tree, and `autoninja -C out/Default` makes the types
# available to the IDE under out/Default/gen (see front_end/tsconfig.json).

import os.path as path
import os
import subprocess
import sys

ROOT_DIRECTORY = path.join(path.dirname(path.abspath(__file__)), '..', '..')

SCRIPTS_BUILD_PATH = path.join(ROOT_DIRECTORY, 'scripts', 'build')

GENERATE_SUPPORTED_CSS_SCRIPT = path.join(SCRIPTS_BUILD_PATH,
                                          'generate_supported_css.py')


def popen(arguments, cwd=ROOT_DIRECTORY, env=os.environ.copy()):
    process = subprocess.Popen([sys.executable] + arguments, cwd=cwd, env=env)

    process.communicate()

    if process.returncode != 0:
        sys.exit(process.returncode)


def main():
    popen([GENERATE_SUPPORTED_CSS_SCRIPT])


if __name__ == '__main__':
    main()
